parameters.query:
SELECT ticket_id, ticket_ref, subject, description, channel
FROM tickets
WHERE ticket_id = {{ $json.ticket_id }};

values.content:
=You are a support ticket triage assistant. Analyze the ticket below and respond with ONLY a valid JSON object (no markdown, no code fences, no extra text) with exactly these keys:
{
  "category": one of ["billing", "technical", "account", "general"],
  "priority": one of ["urgent", "high", "medium", "low"],
  "sentiment": one of ["positive", "neutral", "negative", "frustrated"],
  "summary": a one-sentence summary of the issue,
  "draft_reply": a short, empathetic 2-3 sentence draft reply an agent could send to the customer
}

Ticket Subject: {{ $json.subject }}
Ticket Description: {{ $json.description }}
Channel: {{ $json.channel }}

parameters.jsCode:
// Parse Gemini's JSON response safely, stripping any accidental markdown fences
const raw = $input.item.json.content?.parts?.[0]?.text || '';
let cleaned = raw.trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    category: 'general',
    priority: 'medium',
    sentiment: 'neutral',
    summary: 'Could not auto-classify — needs manual review',
    draft_reply: 'Thank you for reaching out. Our team is reviewing your request and will follow up shortly.'
  };
}

const ticket = $('Fetch Ticket Details').item.json;

const slaHours = { urgent: 2, high: 8, medium: 24, low: 72 };
const hours = slaHours[parsed.priority] || 24;

return {
  json: {
    ticket_id: ticket.ticket_id,
    ticket_ref: ticket.ticket_ref,
    category: parsed.category,
    priority: parsed.priority,
    sentiment: parsed.sentiment,
    ai_summary: parsed.summary,
    ai_draft_reply: parsed.draft_reply,
    sla_hours: hours
  }
};
